# GIVEN — the tree and its helpers. Read them, use them, don't rewrite them.
# -------------------------------------------------------------------------
class Node:
    def __init__(self, name, is_file, parent=None):
        self.name = name
        self.is_file = is_file
        self.parent = parent
        self.children = {}          # name -> Node

    def path(self):
        parts = []
        n = self
        while n is not None:
            if n.name:
                parts.append(n.name)
            n = n.parent
        return "/" + "/".join(reversed(parts))


class FileTree:
    def __init__(self):
        self.root = Node("", False)

    def find(self, path):
        """The Node at `path`, or None if it doesn't exist."""
        node = self.root
        for part in path.split("/"):
            if not part:
                continue
            node = node.children.get(part)
            if node is None:
                return None
        return node

    def iter_files(self, node):
        """Yield every *file* node in the subtree under `node` (DFS)."""
        if node.is_file:
            yield node
            return
        for child in node.children.values():
            yield from self.iter_files(child)

    def add_file(self, path):
        parts = [p for p in path.split("/") if p]
        node = self.root
        for part in parts[:-1]:
            if part not in node.children:
                node.children[part] = Node(part, False, node)
            node = node.children[part]
        leaf = Node(parts[-1], True, node)
        node.children[parts[-1]] = leaf
        return leaf

    def remove_file(self, path):
        node = self.find(path)
        del node.parent.children[node.name]
        return node


