class FileTree {
  constructor() { this.root = new Node("", false); }

  /** The Node at `path`, or null if it doesn't exist. */
  find(path) {
    let node = this.root;
    for (const part of path.split("/").filter(Boolean)) {
      node = node.children.get(part);
      if (!node) return null;
    }
    return node;
  }

  /** Every *file* node in the subtree under `node` (DFS). */
  *iterFiles(node) {
    if (node.isFile) { yield node; return; }
    for (const child of node.children.values()) yield* this.iterFiles(child);
  }

  addFile(path) {
    const parts = path.split("/").filter(Boolean);
    let node = this.root;
    for (const part of parts.slice(0, -1)) {
      if (!node.children.has(part)) node.children.set(part, new Node(part, false, node));
      node = node.children.get(part);
    }
    const leaf = new Node(parts[parts.length - 1], true, node);
    node.children.set(leaf.name, leaf);
    return leaf;
  }

  removeFile(path) {
    const node = this.find(path);
    node.parent.children.delete(node.name);
