// later runs are quick.
import java.util.*;

public class Watchlist {

    // ------------------------------------------------------------
    // GIVEN: the tree and its helpers. Read them, don't rewrite them.
    // ------------------------------------------------------------
    static class Node {
        final String name; final boolean isFile; final Node parent;
        final Map<String, Node> children = new LinkedHashMap<>();
        Node(String name, boolean isFile, Node parent) { this.name = name; this.isFile = isFile; this.parent = parent; }
        String path() {
            Deque<String> parts = new ArrayDeque<>();
            for (Node n = this; n != null; n = n.parent) if (!n.name.isEmpty()) parts.push(n.name);
            return "/" + String.join("/", parts);
        }
    }

    static class FileTree {
        final Node root = new Node("", false, null);
        Node find(String path) { /* given */ Node node = root;
            for (String part : path.split("/")) { if (part.isEmpty()) continue; node = node.children.get(part); if (node == null) return null; }
            return node; }
        /** Every *file* node in the subtree rooted at node (DFS). */
        List<Node> iterFiles(Node node) { List<Node> out = new ArrayList<>(); collect(node, out); return out; }
        private void collect(Node n, List<Node> out) { if (n.isFile) { out.add(n); return; } for (Node c : n.children.values()) collect(c, out); }
        Node addFile(String path) { /* given */ String[] parts = Arrays.stream(path.split("/")).filter(s -> !s.isEmpty()).toArray(String[]::new);
            Node node = root;
            for (int i = 0; i < parts.length - 1; i++) { Node child = node.children.get(parts[i]); if (child == null) { child = new Node(parts[i], false, node); node.children.put(parts[i], child); } node = child; }
            Node leaf = new Node(parts[parts.length - 1], true, node); node.children.put(leaf.name, leaf); return leaf; }
        Node removeFile(String path) { Node node = find(path); node.parent.children.remove(node.name); return node; }
    }

    // ------------------------------------------------------------
    // YOUR CODE
    // ------------------------------------------------------------
    private final FileTree tree;

