def __run_tests__(ns, max_part=3):
    FileTree = ns["FileTree"]; Watchlist = ns["Watchlist"]

    def assert_eq(actual, expected, label):
        if actual != expected:
            raise AssertionError(f"{label}\n   expected {expected!r}\n   got      {actual!r}")

    def build():
        t = FileTree()
        for p in ["/src/main.py", "/src/util.py", "/src/README.md", "/src/net/sock.py",
                  "/src/net/sock_test.py", "/docs/guide.md", "/docs/img/logo.png"]:
            t.add_file(p)
        return t

    def t1_empty():
        w = Watchlist(build()); assert_eq(w.display(), [], "display() on fresh watchlist")

    def t1_single():
        w = Watchlist(build()); w.add_watch("/src", ".py")
        assert_eq(w.display(), ["/src/main.py", "/src/net/sock.py", "/src/net/sock_test.py", "/src/util.py"],
                  "display after add_watch('/src', '.py')")

    def t1_two():
        w = Watchlist(build()); a = w.add_watch("/src", ".py"); b = w.add_watch("/docs")
        assert_eq(w.display(), ["/docs/guide.md", "/docs/img/logo.png", "/src/main.py", "/src/net/sock.py",
                                "/src/net/sock_test.py", "/src/util.py"], "both watches")
        w.remove_watch(a); assert_eq(w.display(), ["/docs/guide.md", "/docs/img/logo.png"], "after removing /src watch")
        w.remove_watch(b); assert_eq(w.display(), [], "after removing both")

    def t1_missing():
        w = Watchlist(build()); x = w.add_watch("/nope"); assert_eq(w.display(), [], "missing root")
        w.remove_watch(x); assert_eq(w.display(), [], "after removing missing-root watch")

    def t2_overlap():
        w = Watchlist(build()); a = w.add_watch("/src"); b = w.add_watch("/src/net", ".py")
        all_ = ["/src/README.md", "/src/main.py", "/src/net/sock.py", "/src/net/sock_test.py", "/src/util.py"]
        assert_eq(w.display(), all_, "both watches")
        w.remove_watch(b); assert_eq(w.display(), all_, "net files still covered by the /src watch")
        w.remove_watch(a); assert_eq(w.display(), [], "nothing left")

    def t2_copy():
        w = Watchlist(build()); w.add_watch("/docs"); d = w.display(); d.append("/garbage")
        assert_eq(w.display(), ["/docs/guide.md", "/docs/img/logo.png"], "cache untouched")

    def t2_hot():
        t = build(); w = Watchlist(t); w.add_watch("/src")
        walks = [0]; orig = t.iter_files
        def spy(node):
            walks[0] += 1
            yield from orig(node)
        t.iter_files = spy
        for _ in range(1000): w.display()
        if walks[0] != 0:
            raise AssertionError(f"display() called iter_files {walks[0]} times across 1000 calls; it should be served from a cache")

    def t3_add():
        t = build(); w = Watchlist(t); a = w.add_watch("/src", ".py"); w.add_watch("/src/net")
        t.add_file("/src/net/new.py"); w.on_file_added("/src/net/new.py")
        if "/src/net/new.py" not in w.display(): raise AssertionError("new file should be displayed")
        w.remove_watch(a)
        if "/src/net/new.py" not in w.display(): raise AssertionError("new file still covered by /src/net watch")
        if "/src/main.py" in w.display(): raise AssertionError("/src/main.py should be gone after removing the /src watch")

    def t3_remove():
        t = build(); w = Watchlist(t); w.add_watch("/src/net")
        t.add_file("/src/net/new.py"); w.on_file_added("/src/net/new.py")
        w.on_file_removed("/src/net/new.py"); t.remove_file("/src/net/new.py")
        assert_eq(w.display(), ["/src/net/sock.py", "/src/net/sock_test.py"], "after remove")
        t.add_file("/src/other.txt"); w.on_file_added("/src/other.txt")
        assert_eq(w.display(), ["/src/net/sock.py", "/src/net/sock_test.py"], "uncovered file ignored")

    tests = [
        (1, "empty watchlist displays nothing", t1_empty),
        (1, "single watch with extension filter", t1_single),
        (1, "two disjoint watches, remove one, remove both", t1_two),
        (1, "watch on a path that doesn't exist is a no-op", t1_missing),
        (2, "overlapping watches: removing one keeps shared files (ref counting)", t2_overlap),
        (2, "display() returns a copy; caller can't corrupt the cache", t2_copy),
        (2, "display() does not re-walk the tree (hot path)", t2_hot),
        (3, "file added under two live watches, then one watch removed", t3_add),
        (3, "file removed while watched; unwatched file added is ignored", t3_remove),
    ]
    for part, name, fn in tests:
        if part > max_part: continue
        try:
            fn(); print(f"PASS|{part}|{name}")
        except BaseException as e:
            msg = str(e) if isinstance(e, AssertionError) else f"{type(e).__name__}: {e}"
            print(f"FAIL|{part}|{name}|{msg}")

