public class WatchlistTests {
    static class SpyTree extends Watchlist.FileTree {
        int walks = 0; boolean counting = false;
        @Override List<Watchlist.Node> iterFiles(Watchlist.Node node) { if (counting) walks++; return super.iterFiles(node); }
    }
    interface Test { void run() throws Exception; }

    static <T extends Watchlist.FileTree> T fill(T t) {
        for (String p : new String[]{"/src/main.py", "/src/util.py", "/src/README.md", "/src/net/sock.py",
                                     "/src/net/sock_test.py", "/docs/guide.md", "/docs/img/logo.png"}) t.addFile(p);
        return t;
    }
    static Watchlist.FileTree build() { return fill(new Watchlist.FileTree()); }
    static List<String> L(String... xs) { return Arrays.asList(xs); }
    static void check(Object actual, Object expected, String label) {
        if (!Objects.equals(actual, expected)) throw new AssertionError(label + "\n   expected " + expected + "\n   got      " + actual);
    }
    static void yes(boolean c, String msg) { if (!c) throw new AssertionError(msg); }

    public static void main(String[] args) {
        int maxPart = args.length > 0 ? Integer.parseInt(args[0]) : 3;
        LinkedHashMap<String, Test> tests = new LinkedHashMap<>();
        tests.put("1|empty watchlist displays nothing", () -> {
            Watchlist w = new Watchlist(build()); check(w.display(), L(), "display() on fresh watchlist"); });
        tests.put("1|single watch with extension filter", () -> {
            Watchlist w = new Watchlist(build()); w.addWatch("/src", ".py");
            check(w.display(), L("/src/main.py", "/src/net/sock.py", "/src/net/sock_test.py", "/src/util.py"), "display after addWatch(\"/src\", \".py\")"); });
        tests.put("1|two disjoint watches, remove one, remove both", () -> {
