            check(w.display(), L("/docs/guide.md", "/docs/img/logo.png", "/src/main.py", "/src/net/sock.py", "/src/net/sock_test.py", "/src/util.py"), "both watches");
            w.removeWatch(a); check(w.display(), L("/docs/guide.md", "/docs/img/logo.png"), "after removing /src watch");
            w.removeWatch(b); check(w.display(), L(), "after removing both"); });
        tests.put("1|watch on a path that doesn't exist is a no-op", () -> {
            Watchlist w = new Watchlist(build()); int x = w.addWatch("/nope", null); check(w.display(), L(), "missing root");
            w.removeWatch(x); check(w.display(), L(), "after removing missing-root watch"); });
        tests.put("2|overlapping watches: removing one keeps shared files (ref counting)", () -> {
            Watchlist w = new Watchlist(build()); int a = w.addWatch("/src", null); int b = w.addWatch("/src/net", ".py");
            List<String> all = L("/src/README.md", "/src/main.py", "/src/net/sock.py", "/src/net/sock_test.py", "/src/util.py");
