import java.io.File;
import java.lang.reflect.InvocationTargetException;
import java.lang.reflect.Method;
import java.net.URL;
import java.net.URLClassLoader;

// Loads each run's freshly compiled classes in a new class loader, so a rerun never sees stale code.
public class PadRunner {
    public static void main(String[] args) throws Exception {
        if (args[0].equals("--mkdir")) { new File(args[1]).mkdirs(); return; }
        URLClassLoader loader = new URLClassLoader(new URL[]{ new File(args[0]).toURI().toURL() }, PadRunner.class.getClassLoader());
        try {
            Method main = loader.loadClass("WatchlistTests").getMethod("main", String[].class);
            main.invoke(null, (Object) new String[]{ args[1] });
        } catch (InvocationTargetException e) {
            System.out.println("__PAD_ERROR__");
            e.getCause().printStackTrace(System.out);
        } catch (Throwable e) {
            System.out.println("__PAD_ERROR__");
            e.printStackTrace(System.out);
        }
        System.out.println("__PAD_DONE__");
        System.out.flush();
    }
}

