from bisect import insort, bisect_left


def matches(name, ext):
    """A file matches a watch when there's no filter, or its name ends with it."""
    return ext is None or name.endswith(ext)


class Watchlist:
    """
    Invariant: a path is in the display exactly when its reference count
    (number of active watches covering it) is above zero.

      watches:  id -> (root_path, ext)      what's active
      refs:     path -> count               how many watches cover the path
      display:  sorted list of paths        every path with count > 0
    """

    def __init__(self, tree):
        self.tree = tree
        self.watches = {}
        self.next_id = 0
        self.refs = {}
        self.sorted_display = []

    # ---- Part 1 (already in its Part 2 shape; see talk track) ----
    def add_watch(self, root_path, ext=None):
        watch_id = self.next_id
        self.next_id += 1
        self.watches[watch_id] = (root_path, ext)
        for f in self._covered_files(root_path, ext):
            self._acquire(f.path())
        return watch_id

    def remove_watch(self, watch_id):
        root_path, ext = self.watches.pop(watch_id)
        for f in self._covered_files(root_path, ext):
            self._release(f.path())

    def display(self):
        return list(self.sorted_display)      # copy: callers can't corrupt the cache

    # ---- Part 3 ----
    def on_file_added(self, path):
        for _ in range(self._covering_watch_count(path)):
            self._acquire(path)

    def on_file_removed(self, path):
        for _ in range(self._covering_watch_count(path)):
            self._release(path)

    # ---- helpers ----
    def _covered_files(self, root_path, ext):
        root = self.tree.find(root_path)
        if root is None:
            return []
        return [f for f in self.tree.iter_files(root) if matches(f.name, ext)]

    def _covering_watch_count(self, path):
        """How many active watches cover this one file."""
        node = self.tree.find(path)
        ancestors = set()
        n = node
        while n is not None:
            ancestors.add(n.path())
            n = n.parent
        return sum(1 for root_path, ext in self.watches.values()
                   if root_path in ancestors and matches(node.name, ext))

    def _acquire(self, path):
        count = self.refs.get(path, 0)
        self.refs[path] = count + 1
        if count == 0:
            insort(self.sorted_display, path)   # from bisect

    def _release(self, path):
        count = self.refs[path]
        if count == 1:
            del self.refs[path]
            self.sorted_display.pop(bisect_left(self.sorted_display, path))
        else:
            self.refs[path] = count - 1

