/* Layout: one-screen pad, CoderPad-style — question rail on the left, editor + console stacked on the right. Dark-first. */
:root{
  --bg:#0f1318; --panel:#161b22; --panel-2:#1b212b; --line:#273040; --line-strong:#334055;
  --fg:#e3e8ef; --muted:#8e9ab0; --faint:#5f6b80;
  --accent:#4cc38a; --accent-ink:#0b1a12; --accent-soft:rgba(76,195,138,.14);
  --warn:#e9b44c; --bad:#ff7a7a; --bad-soft:rgba(255,122,122,.12); --good:#4cc38a; --good-soft:rgba(76,195,138,.14);
  --info:#7cb7ff; --info-soft:rgba(124,183,255,.12);
  --sel:rgba(124,183,255,.25);
  --ui:"IBM Plex Sans",system-ui,-apple-system,"Segoe UI",sans-serif;
  --mono:"JetBrains Mono",ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;
  --hl-kw:#c792ea; --hl-str:#9ccc65; --hl-num:#f78c6c; --hl-cm:#6c7a91; --hl-fn:#82aaff; --hl-cls:#ffcb6b; --hl-bi:#89ddff;
  color-scheme:dark;
}
@media (prefers-color-scheme: light){
  :root:not([data-theme="dark"]){
    --bg:#f3f5f8; --panel:#ffffff; --panel-2:#f6f8fb; --line:#dfe4ec; --line-strong:#c9d1dd;
    --fg:#1a2130; --muted:#5b6678; --faint:#8a94a6;
    --accent:#1d9a63; --accent-ink:#ffffff; --accent-soft:rgba(29,154,99,.12);
    --warn:#b07a12; --bad:#c43c3c; --bad-soft:rgba(196,60,60,.1); --good:#1d9a63; --good-soft:rgba(29,154,99,.12);
    --info:#2466c4; --info-soft:rgba(36,102,196,.1);
    --sel:rgba(36,102,196,.2);
    --hl-kw:#8a3fc1; --hl-str:#2f7d2f; --hl-num:#b4541c; --hl-cm:#7a8494; --hl-fn:#1f5fbf; --hl-cls:#a06a00; --hl-bi:#0b7a8a;
    color-scheme:light;
  }
}
:root[data-theme="light"]{
  --bg:#f3f5f8; --panel:#ffffff; --panel-2:#f6f8fb; --line:#dfe4ec; --line-strong:#c9d1dd;
  --fg:#1a2130; --muted:#5b6678; --faint:#8a94a6;
  --accent:#1d9a63; --accent-ink:#ffffff; --accent-soft:rgba(29,154,99,.12);
  --warn:#b07a12; --bad:#c43c3c; --bad-soft:rgba(196,60,60,.1); --good:#1d9a63; --good-soft:rgba(29,154,99,.12);
  --info:#2466c4; --info-soft:rgba(36,102,196,.1);
  --sel:rgba(36,102,196,.2);
  --hl-kw:#8a3fc1; --hl-str:#2f7d2f; --hl-num:#b4541c; --hl-cm:#7a8494; --hl-fn:#1f5fbf; --hl-cls:#a06a00; --hl-bi:#0b7a8a;
  color-scheme:light;
}
*{box-sizing:border-box}
html,body{height:100%}
body{margin:0;background:var(--bg);color:var(--fg);font-family:var(--ui);font-size:14px;line-height:1.5;overflow:hidden}
button{font:inherit;color:inherit;background:none;border:0;cursor:pointer}
button:focus-visible,select:focus-visible,textarea:focus-visible,[tabindex]:focus-visible{outline:2px solid var(--info);outline-offset:1px}
code,pre,kbd{font-family:var(--mono)}
code{font-size:.92em;background:var(--panel-2);border:1px solid var(--line);border-radius:4px;padding:0 .3em}
pre code{background:none;border:0;padding:0;font-size:inherit}
kbd{font-size:.8em;border:1px solid var(--line-strong);border-bottom-width:2px;border-radius:4px;padding:0 .35em;color:var(--muted)}
a{color:var(--info)}

.app{height:100%;display:grid;grid-template-rows:auto 1fr;}
.topbar{display:flex;align-items:center;gap:14px;padding:8px 16px;border-bottom:1px solid var(--line);background:var(--panel);flex-wrap:wrap}
.brand{display:flex;align-items:center;gap:10px;font-weight:600;letter-spacing:.01em}
.brand .dot{width:10px;height:10px;border-radius:50%;background:var(--accent);box-shadow:0 0 0 3px var(--accent-soft)}
.brand small{font-weight:400;color:var(--muted)}
.spacer{flex:1}
.timer{display:flex;align-items:center;gap:8px;font-family:var(--mono);font-variant-numeric:tabular-nums;font-size:15px;color:var(--muted)}
.timer .t{color:var(--fg);min-width:5ch;text-align:right}
.timer.low .t{color:var(--warn)}
.timer.over .t{color:var(--bad)}
.btn{display:inline-flex;align-items:center;gap:6px;padding:6px 12px;border-radius:6px;border:1px solid var(--line-strong);background:var(--panel-2);font-weight:500;line-height:1.2}
.btn:hover{border-color:var(--muted)}
.btn.primary{background:var(--accent);color:var(--accent-ink);border-color:transparent}
.btn.primary:hover{filter:brightness(1.08)}
.btn.ghost{border-color:transparent;color:var(--muted)}
.btn.ghost:hover{color:var(--fg);background:var(--panel-2)}
.btn.sm{padding:4px 9px;font-size:13px}
.btn:disabled{opacity:.5;cursor:default}
select.lang{font:inherit;color:var(--fg);background:var(--panel-2);border:1px solid var(--line-strong);border-radius:6px;padding:6px 10px}

.main{display:grid;grid-template-columns:minmax(300px,42%) 1fr;min-height:0}
.rail{border-right:1px solid var(--line);display:flex;flex-direction:column;min-height:0;min-width:0;background:var(--panel)}
.tabs{display:flex;gap:2px;padding:6px 10px 0;border-bottom:1px solid var(--line);background:var(--panel)}
.tab{padding:8px 12px;border-radius:6px 6px 0 0;color:var(--muted);font-weight:500;border:1px solid transparent;border-bottom:0;position:relative;top:1px}
.tab[aria-selected="true"]{color:var(--fg);background:var(--bg);border-color:var(--line)}
.tab .pill{display:inline-block;min-width:1.4em;padding:0 .4em;margin-left:.4em;border-radius:999px;background:var(--accent-soft);color:var(--accent);font-size:11px;font-weight:600;text-align:center}
.panel{overflow:auto;padding:18px 20px 32px;min-height:0;background:var(--bg)}
.panel h2{font-size:18px;margin:0 0 4px;text-wrap:balance}
.panel h3{font-size:14px;margin:24px 0 8px;text-transform:uppercase;letter-spacing:.06em;color:var(--muted)}
.panel p{margin:0 0 10px;max-width:68ch}
.panel ul,.panel ol{margin:0 0 10px;padding-left:20px;max-width:68ch}
.panel li{margin:3px 0}
.meta{color:var(--muted);font-size:13px;margin-bottom:14px}
.quote{border-left:3px solid var(--line-strong);padding:6px 12px;margin:10px 0 14px;color:var(--fg);background:var(--panel);border-radius:0 6px 6px 0;max-width:68ch}
.quote .who{display:block;font-size:12px;color:var(--muted);text-transform:uppercase;letter-spacing:.06em;margin-bottom:2px}
.treebox{background:var(--panel);border:1px solid var(--line);border-radius:6px;padding:10px 12px;margin:8px 0 12px;overflow-x:auto;font-size:13px;line-height:1.45}
.part{border:1px solid var(--line);border-radius:8px;padding:14px 16px;margin:12px 0;background:var(--panel)}
.part.locked{border-style:dashed;background:transparent}
.part .ph{display:flex;align-items:center;gap:10px;margin-bottom:8px}
.part .ph h4{margin:0;font-size:15px}
.part .tag{font-size:11px;font-weight:600;letter-spacing:.06em;text-transform:uppercase;color:var(--muted);border:1px solid var(--line-strong);border-radius:4px;padding:1px 6px}
.part.locked .lockmsg{color:var(--muted);display:flex;gap:10px;align-items:center;flex-wrap:wrap}
.api{white-space:pre;font-family:var(--mono);font-size:12.5px;background:var(--panel-2);border:1px solid var(--line);border-radius:6px;padding:8px 10px;overflow-x:auto;margin:8px 0}
.api .c{color:var(--hl-cm)}
.reveal{border:1px solid var(--line);border-radius:6px;margin:6px 0;background:var(--panel)}
.reveal > button{width:100%;text-align:left;padding:9px 12px;display:flex;gap:10px;align-items:flex-start}
.reveal > button .n{color:var(--muted);font-family:var(--mono);font-size:12px;padding-top:3px}
.reveal > button .chev{margin-left:auto;color:var(--faint);transition:transform .15s}
.reveal.open > button .chev{transform:rotate(90deg)}
.reveal .body{padding:0 12px 10px 34px;color:var(--fg)}
.reveal .body .ans{margin-top:6px;padding:8px 10px;border-left:3px solid var(--info);background:var(--info-soft);border-radius:0 6px 6px 0}
.reveal .body .ans b{color:var(--info)}
.reveal .body .decode{margin-top:6px;padding:8px 10px;border-left:3px solid var(--accent);background:var(--accent-soft);border-radius:0 6px 6px 0}
.reveal .body .decode b{color:var(--accent)}
.hid{display:none}
.decoder{width:100%;border-collapse:collapse;font-size:13px;margin:8px 0 14px}
.decoder td{padding:7px 8px;border-top:1px solid var(--line);vertical-align:top}
.decoder td:first-child{color:var(--fg);font-style:italic;width:44%}
.decoder td:last-child{color:var(--muted)}
.check{display:flex;gap:10px;align-items:flex-start;padding:7px 8px;border-radius:6px;cursor:pointer}
.check:hover{background:var(--panel)}
.check input{margin-top:4px;accent-color:var(--accent)}
.check.done span{color:var(--muted);text-decoration:line-through}
.score{font-family:var(--mono);font-size:13px;color:var(--muted);margin:4px 0 10px}
.timeline{display:grid;grid-template-columns:auto 1fr;gap:4px 14px;font-size:13px;margin:8px 0 14px}
.timeline .tm{font-family:var(--mono);color:var(--accent);font-variant-numeric:tabular-nums;white-space:nowrap}
.callout{border:1px solid var(--warn);background:rgba(233,180,76,.08);border-radius:8px;padding:12px 14px;margin:14px 0;max-width:68ch}
.callout b{color:var(--warn)}
.lock{border:1px dashed var(--line-strong);border-radius:8px;padding:28px 18px;text-align:center;color:var(--muted);max-width:68ch}
.sol pre{background:var(--panel);border:1px solid var(--line);border-radius:6px;padding:10px 12px;overflow-x:auto;font-size:12.5px;line-height:1.5;margin:8px 0 14px}
.ctab{width:100%;border-collapse:collapse;font-size:13px;margin:8px 0 14px;font-variant-numeric:tabular-nums}
.ctab th,.ctab td{text-align:left;padding:6px 8px;border-top:1px solid var(--line)}
.ctab th{color:var(--muted);font-weight:500;border-top:0}
.ctab code{white-space:nowrap}
.say{margin:8px 0 12px;padding:10px 12px;border-radius:6px;background:var(--panel);border:1px solid var(--line);max-width:68ch}
.say .lbl{display:block;font-size:11px;text-transform:uppercase;letter-spacing:.06em;color:var(--accent);font-weight:600;margin-bottom:4px}
.say p{margin:0 0 6px}

.work{display:grid;grid-template-rows:1fr auto;min-height:0;min-width:0}
.editor{position:relative;display:grid;grid-template-columns:auto 1fr;min-height:0;background:var(--panel);font-family:var(--mono);font-size:13.5px;line-height:1.55;tab-size:4}
.gutter{padding:12px 10px 12px 14px;text-align:right;color:var(--faint);user-select:none;overflow:hidden;border-right:1px solid var(--line);white-space:pre;font-variant-numeric:tabular-nums}
.codewrap{position:relative;min-width:0;overflow:hidden}
.codewrap pre,.codewrap textarea{margin:0;padding:12px 16px 12px 14px;font:inherit;line-height:inherit;tab-size:4;white-space:pre;word-wrap:normal;overflow-wrap:normal}
.codewrap pre{position:absolute;inset:0;overflow:hidden;pointer-events:none;color:var(--fg)}
.codewrap textarea{position:absolute;inset:0;width:100%;height:100%;resize:none;border:0;outline:0;background:transparent;color:transparent;caret-color:var(--fg);overflow:auto}
.codewrap textarea::selection{background:var(--sel)}
.hljs-keyword,.hljs-literal{color:var(--hl-kw)}
.hljs-string,.hljs-regexp{color:var(--hl-str)}
.hljs-number{color:var(--hl-num)}
.hljs-comment,.hljs-doctag{color:var(--hl-cm);font-style:italic}
.hljs-title.function_,.hljs-title{color:var(--hl-fn)}
.hljs-title.class_,.hljs-type{color:var(--hl-cls)}
.hljs-built_in,.hljs-meta{color:var(--hl-bi)}
.hljs-params{color:var(--fg)}
.hljs-attr,.hljs-property{color:var(--fg)}
.hljs-variable.language_{color:var(--hl-kw)}

.console{border-top:1px solid var(--line);background:var(--panel);display:grid;grid-template-rows:auto minmax(120px,26vh);min-height:0}
.console .bar{display:flex;align-items:center;gap:6px;padding:4px 10px;border-bottom:1px solid var(--line)}
.console .bar .ctab-btn{padding:5px 10px;border-radius:5px;color:var(--muted);font-weight:500;font-size:13px}
.console .bar .ctab-btn[aria-selected="true"]{color:var(--fg);background:var(--panel-2)}
.console .bar .status{margin-left:auto;font-size:12.5px;color:var(--muted);font-family:var(--mono)}
.console .bar .status.ok{color:var(--good)}
.console .bar .status.bad{color:var(--bad)}
.out{overflow:auto;padding:10px 14px;font-family:var(--mono);font-size:12.5px;line-height:1.5;white-space:pre-wrap;word-break:break-word;color:var(--fg);min-height:0}
.out .dim{color:var(--muted)}
.out .err{color:var(--bad)}
.tests{overflow:auto;padding:8px 10px;min-height:0;font-size:13px}
.tgroup{margin:4px 0 10px}
.tgroup .gh{display:flex;align-items:center;gap:8px;color:var(--muted);font-size:12px;text-transform:uppercase;letter-spacing:.06em;padding:4px 6px}
.trow{display:grid;grid-template-columns:18px 1fr;gap:8px;padding:5px 6px;border-radius:5px;align-items:start}
.trow .ic{font-family:var(--mono);font-weight:600;text-align:center}
.trow.pass .ic{color:var(--good)} .trow.fail .ic{color:var(--bad)} .trow.wait .ic{color:var(--faint)} .trow.locked{color:var(--faint)}
.trow .msg{font-family:var(--mono);font-size:12px;color:var(--bad);white-space:pre-wrap;margin-top:3px}
.trow.fail{background:var(--bad-soft)}
.trow.pass{background:transparent}

.toast{position:fixed;left:50%;bottom:calc(18px + env(safe-area-inset-bottom,0px));transform:translateX(-50%);background:var(--panel-2);border:1px solid var(--line-strong);border-radius:8px;padding:10px 14px;box-shadow:0 8px 24px rgba(0,0,0,.35);max-width:min(92vw,520px);z-index:9}
.toast .btn{margin-left:8px}
.gap{height:8px}

@media (max-width: 860px){
  body{overflow:auto}
  .app{height:auto;min-height:100%}
  .main{grid-template-columns:1fr;grid-template-rows:auto auto}
  .rail{border-right:0;border-bottom:1px solid var(--line);max-height:70vh}
  .panel{max-height:62vh}
  .editor{height:52vh}
  .console{grid-template-rows:auto 30vh}
}
@media (prefers-reduced-motion: reduce){ *{transition:none!important} }
